head.script:
scwin.test = function(row, col) {
    var obj = {};
    if (row == 0) {
        obj.increment = 2;
        obj.minValue = 0;
        obj.maxValue = 10;
        return obj;
    } else if (row == 1) {
        obj.increment = 4;
        obj.minValue = 0;
        obj.maxValue = 20;
        return obj;
    } else if (row == 2) {
        obj.increment = 8;
        obj.minValue = 0;
        obj.maxValue = 40;
        return obj;
    }
};
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.checkDisplay = function(id) {
    if (WebSquare.wUnit.getJq(id).css("display") == "block") {
        return true;
    } else if (WebSquare.wUnit.getJq(id).css("display") == "inline-block") {
        return true;
    } else {
        return false;
    }
}
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getJq('#wq_uuid_3_cell_0_1').hasClass('gridBodyDefault_spinner') == false;
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getJq('#wq_uuid_3_cell_1_1').hasClass('gridBodyDefault_spinner') == false;
}
scwin.checkVal3 = function() {
    return WebSquare.wUnit.getJq('#wq_uuid_3_cell_2_1').hasClass('gridBodyDefault_spinner') == false;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. Source 탭 또는 Property 탭에서 col2 의 inputType 부분을 확인한다.
    //1. Check the inputType part of col2 in the Source tab or Property tab.
    //Verify step 1. inputType="spinner"
    //1. inputType = "spinner"
    //Test step 2. viewType 부분을 확인한다.
    //2. Check the viewType part.
    //Verify step 2. viewType ="default"
    //2. viewType = "default"
    //Test step 3. 브라우저에서 name2 컬럼을 확인한다.
    //3. Check the name2 column in your browser.
    //Verify step 3. name2 컬럼에 spinner 표시가 없다.
    //3. There is no spinner mark in the name2 column.           
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 4. name2 임의의 컬럼을 더블클릭한다.
    //4. Double-click any column in name2.
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'wq_uuid_3_cell_1_1')");
    //Verify step 4. Edit 모드로 진입하면서 spinner 표시가 생긴다.
    //4. Enter the Edit mode and the spinner display appears.
    WebSquare.wUnit.addCommand("assert", "scwin.checkDisplay('#G_'+$p.id+'wq_uuid_3___spinner_col2')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkDisplay('#G_'+$p.id+'wq_uuid_3___spinner_col2___input')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 30-Jan-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
